import { randomUUID } from "node:crypto";
const AGENT_ID_PATTERN = /^bc-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** A fresh Cloud Agents API agent id, chosen before the launch. */
export function newCloudAgentId() {
    return `bc-${randomUUID()}`;
}
/** The `bc-<uuid>` form the Cloud Agents API takes as a client-chosen agent id. */
export function isCloudAgentId(value) {
    return AGENT_ID_PATTERN.test(value);
}
